import itertools
samples=[((6,1),(4,4),31,3),((3,0),(6,1),16,15),((3,1),(1,2),6,24)]
# zero indexed
features=['ax','ay','bx','by']
vals=[{'ax':a[0],'ay':a[1],'bx':b[0],'by':b[1]} for a,b,_,_ in samples]
# generate unary simple and binary operations depth1
unary={}
for f in features:
    unary[f]=[v[f] for v in vals]
    unary['~'+f]=[(~v[f])&31 for v in vals]
    unary[f+'+1']=[v[f]+1 for v in vals]
    unary['1<<'+f]=[(1<<v[f])&31 for v in vals]
ops={'+':lambda x,y:(x+y)&31,'-':lambda x,y:(x-y)&31,'*':lambda x,y:(x*y)&31,'^':lambda x,y:x^y,'|':lambda x,y:x|y,'&':lambda x,y:x&y}
matches=[[],[]]
for (n1,v1),(n2,v2) in itertools.product(unary.items(),repeat=2):
    for op,fn in ops.items():
        out=[fn(x,y) for x,y in zip(v1,v2)]
        for k in range(2):
            if out==[s[2+k] for s in samples]:matches[k].append(f'{n1}{op}{n2}')
matches
